#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Stack {
    Rust,
    Node,
    Go,
    Python,
    None,
}

impl Stack {
    #[must_use]
    pub fn parse(s: &str) -> Option<Stack> {
        Some(match s {
            "rust" => Stack::Rust,
            "node" => Stack::Node,
            "go" => Stack::Go,
            "python" => Stack::Python,
            "none" => Stack::None,
            _ => return None,
        })
    }

    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Stack::Rust => "rust",
            Stack::Node => "node",
            Stack::Go => "go",
            Stack::Python => "python",
            Stack::None => "none",
        }
    }

    /// From the build file at the project root.
    #[must_use]
    pub fn detect(root: &Path) -> Stack {
        let has = |f: &str| root.join(f).is_file();
        if has("Cargo.toml") {
            Stack::Rust
        } else if has("package.json") {
            Stack::Node
        } else if has("go.mod") {
            Stack::Go
        } else if has("pyproject.toml") || has("setup.py") {
            Stack::Python
        } else {
            Stack::None
        }
    }

    /// The `[[gauntlet.step]]`s a new `ferrule.toml` starts with.
    fn gauntlet(self) -> &'static [(&'static str, &'static str)] {
        match self {
            Stack::Rust => &[
                ("fmt", r#"["cargo", "fmt", "--check"]"#),
                (
                    "clippy",
                    r#"["cargo", "clippy", "--workspace", "--all-targets", "--", "-D", "warnings"]"#,
                ),
                ("test", r#"["cargo", "test", "--workspace"]"#),
            ],
            Stack::Node => &[("test", r#"["npm", "test"]"#)],
            Stack::Go => &[
                ("vet", r#"["go", "vet", "./..."]"#),
                ("test", r#"["go", "test", "./..."]"#),
            ],
            Stack::Python => &[("test", r#"["python", "-m", "pytest"]"#)],
            Stack::None => &[],
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Hooks {
    /// Through the project's lefthook configuration.
    Lefthook,
    /// Written into the repository's hooks directory.
    Git,
    /// Another hook manager: the user wires them up.
    Manual,
}

impl Hooks {
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Hooks::Lefthook => "lefthook",
            Hooks::Git => "git",
            Hooks::Manual => "manual",
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct Options {
    pub stack: Option<Stack>,
    pub force: bool,
}

#[derive(Debug)]
pub enum Error {
    Io(std::io::Error),
    /// A file at a generated path that ferrule never wrote.
    Foreign(String),
    /// `.claude/settings.json` that is not a JSON object.
    Settings(String),
    Lock(String),
    /// `ferrule.toml` that does not load.
    Config(String),
    /// A file whose ferrule block markers are unpaired or repeated: the
    /// path and what is wrong.
    Markers(String, String),
}

impl From<std::io::Error> for Error {
    fn from(e: std::io::Error) -> Self {
        Error::Io(e)
    }
}

impl Error {
    /// The `<verb>=refused` line: `foreign` names the path, the others say
    /// what was wrong in `detail=`.
    #[must_use]
    pub fn refusal(&self, verb: &'static str) -> Refusal {
        const FIX: &str = "fix the file the detail names, then rerun";
        match self {
            Error::Foreign(p) => Refusal::new(verb, "foreign")
                .field("path", p)
                .hint("--force overwrites it"),
            Error::Settings(_) => Refusal::new(verb, "settings")
                .detail(self.to_string())
                .hint(FIX),
            Error::Lock(_) => Refusal::new(verb, "lock")
                .detail(self.to_string())
                .hint(FIX),
            Error::Config(_) => Refusal::new(verb, "config")
                .detail(self.to_string())
                .hint(FIX),
            Error::Markers(p, _) => Refusal::new(verb, "markers")
                .field("path", p)
                .detail(self.to_string())
                .hint("leave one begin and one end marker in the file, then rerun"),
            Error::Io(_) => Refusal::new(verb, "io").detail(self.to_string()).hint(FIX),
        }
    }
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Error::Io(e) => write!(f, "{e}"),
            Error::Foreign(p) => write!(f, "{p} exists and ferrule did not write it"),
            Error::Settings(e) => write!(f, ".claude/settings.json: {e}"),
            Error::Lock(e) => write!(f, "{LOCK}: {e}"),
            Error::Config(e) => write!(f, "{CONFIG}: {e}"),
            Error::Markers(p, e) => write!(f, "{p}: {e}"),
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Error::Io(e) => Some(e),
            Error::Foreign(_)
            | Error::Settings(_)
            | Error::Lock(_)
            | Error::Config(_)
            | Error::Markers(..) => None,
        }
    }
}

/// What install did, in the order it did it.
#[derive(Debug, Default)]
pub struct Report {
    pub written: Vec<String>,
    /// Edited files kept: (path, the `.ferrule-new` path, `+a/-b`).
    pub kept: Vec<(String, String, String)>,
    pub hints: Vec<String>,
    pub stack: Option<Stack>,
    pub hooks: Option<Hooks>,
    pub viewer: bool,
}

/// FNV-1a over the bytes: stable across versions and platforms.
pub(crate) fn hash(text: &str) -> String {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in text.bytes() {
        h ^= u64::from(b);
        h = h.wrapping_mul(0x0100_0000_01b3);
    }
    format!("{h:016x}")
}

#[derive(Debug, Default, Deserialize)]
#[serde(default)]
struct Lock {
    version: String,
    /// `ferrule setup install` added the `@AGENTS.md` line to `CLAUDE.md`.
    claude_md: bool,
    /// The `permissions.deny` rules ferrule added to the settings.
    deny: Vec<String>,
    /// Generated path (or `<file>#ferrule` for a block) → hash.
    files: BTreeMap<String, String>,
}

fn quote(s: &str) -> String {
    format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\""))
}

impl Lock {
    fn load(root: &Path) -> Result<Lock, Error> {
        match std::fs::read_to_string(root.join(LOCK)) {
            Ok(t) => toml::from_str(&t).map_err(|e| Error::Lock(e.to_string())),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Ok(Lock::default()),
            Err(e) => Err(e.into()),
        }
    }

    fn text(&self) -> String {
        let mut out = format!(
            "# generated by ferrule {VERSION}, never edit\nversion = {}\n",
            quote(&self.version)
        );
        let _ = writeln!(out, "claude_md = {}", self.claude_md);
        let deny: Vec<String> = self.deny.iter().map(|d| quote(d)).collect();
        let _ = writeln!(out, "deny = [{}]", deny.join(", "));
        out.push_str("\n[files]\n");
        for (k, v) in &self.files {
            let _ = writeln!(out, "{} = {}", quote(k), quote(v));
        }
        out
    }
}

/// One thing install keeps in the project.
#[derive(Debug, Clone)]
enum Item {
    /// A whole file ferrule owns.
    File {
        path: String,
        text: String,
        exec: bool,
    },
    /// A marked block inside a project file; the file is created when
    /// missing.
    Block {
        path: String,
        begin: &'static str,
        end: &'static str,
        body: String,
    },
}

impl Item {
    fn key(&self) -> String {
        match self {
            Item::File { path, .. } => path.clone(),
            Item::Block { path, .. } => format!("{path}#ferrule"),
        }
    }

    fn path(&self) -> &str {
        match self {
            Item::File { path, .. } | Item::Block { path, .. } => path,
        }
    }

    /// What the lock hashes: the file, or the block with its markers.
    fn expected(&self) -> String {
        match self {
            Item::File { text, .. } => text.clone(),
            Item::Block {
                begin, end, body, ..
            } => format!("{begin}\n{body}{end}\n"),
        }
    }

    fn current(&self, root: &Path) -> Option<String> {
        let text = std::fs::read_to_string(root.join(self.path())).ok()?;
        match self {
            Item::File { .. } => Some(text),
            Item::Block { begin, end, .. } => {
                block(&text, begin, end).map(|(s, e)| text[s..e].to_owned())
            }
        }
    }

    /// The file's whole new text.
    fn render(&self, root: &Path) -> String {
        match self {
            Item::File { text, .. } => text.clone(),
            Item::Block { begin, end, .. } => {
                let old = std::fs::read_to_string(root.join(self.path())).unwrap_or_default();
                let new = self.expected();
                match block(&old, begin, end) {
                    Some((s, e)) => format!("{}{new}{}", &old[..s], &old[e..]),
                    None if old.is_empty() => new,
                    None => format!(
                        "{}{}\n{new}",
                        old,
                        if old.ends_with('\n') { "" } else { "\n" }
                    ),
                }
            }
        }
    }
}

/// The byte spans of the lines that are exactly `marker`, `\r\n` or `\n`
/// endings included.
fn marker_lines(text: &str, marker: &str) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let mut at = 0;
    for line in text.split_inclusive('\n') {
        if line.trim_end_matches(['\n', '\r']) == marker {
            out.push((at, at + line.len()));
        }
        at += line.len();
    }
    out
}

/// What is wrong with the file's markers, if anything: a block ferrule
/// cannot place without guessing which lines are its own.
fn marker_problem(text: &str, begin: &str, end: &str) -> Option<String> {
    let (b, e) = (marker_lines(text, begin), marker_lines(text, end));
    match (b.as_slice(), e.as_slice()) {
        ([], []) => None,
        ([(s, _)], [(t, _)]) if s < t => None,
        ([_], [_]) => Some(format!("'{end}' comes before '{begin}'")),
        ([], _) => Some(format!("'{end}' without '{begin}'")),
        (_, []) => Some(format!("'{begin}' without '{end}'")),
        _ => Some(format!("'{begin}' or '{end}' appears more than once")),
    }
}

/// The byte span of the marked block, end line included: one begin line
/// and the first end line after it.
fn block(text: &str, begin: &str, end: &str) -> Option<(usize, usize)> {
    let (s, _) = *marker_lines(text, begin).first()?;
    let (_, e) = *marker_lines(text, end).iter().find(|(t, _)| *t > s)?;
    Some((s, e))
}

/// Refuses a block item whose file has unpaired or repeated markers.
fn check_markers(root: &Path, items: &[Item]) -> Result<(), Error> {
    for item in items {
        if let Item::Block { begin, end, .. } = item
            && let Ok(text) = std::fs::read_to_string(root.join(item.path()))
            && let Some(why) = marker_problem(&text, begin, end)
        {
            return Err(Error::Markers(item.path().to_owned(), why));
        }
    }
    Ok(())
}

fn versioned(t: &str) -> String {
    t.replace("{version}", VERSION)
}

/// The project's lefthook configuration file, if it has one.
fn lefthook(root: &Path) -> Option<&'static str> {
    LEFTHOOK_FILES
        .iter()
        .copied()
        .find(|f| root.join(f).is_file())
}

const LEFTHOOK_YML: &str = "# generated by ferrule {version}, edit .ferrule/ instead
pre-commit:
  commands:
    ferrule-main-branch:
      run: .ferrule/ferrule hook git pre-commit
commit-msg:
  commands:
    ferrule-trailers:
      run: .ferrule/ferrule hook git commit-msg {1}
pre-push:
  commands:
    ferrule-main-branch:
      run: .ferrule/ferrule hook git pre-push {1} {2}
      use_stdin: true
";

/// Every file and block install keeps, for the project as it stands.
fn items(root: &Path) -> Vec<Item> {
    let mut out = vec![
        Item::File {
            path: ".ferrule/ferrule".into(),
            text: versioned(SHIM),
            exec: true,
        },
        Item::File {
            path: ".ferrule/.gitignore".into(),
            text: versioned(GITIGNORE),
            exec: false,
        },
    ];
    for (name, text) in AGENTS {
        out.push(Item::File {
            path: format!(".claude/agents/fe-{name}.md"),
            text: versioned(text),
            exec: false,
        });
    }
    for (name, text) in SKILLS {
        out.push(Item::File {
            path: format!(".claude/skills/fe-{name}/SKILL.md"),
            text: versioned(text),
            exec: false,
        });
    }
    out.push(Item::Block {
        path: "AGENTS.md".into(),
        begin: "<!-- ferrule:begin -->",
        end: "<!-- ferrule:end -->",
        body: AGENTS_BLOCK.to_owned(),
    });
    if let Some(file) = lefthook(root)
        && !foreign_extends(root, file)
    {
        out.push(Item::File {
            path: ".ferrule/lefthook.yml".into(),
            text: versioned(LEFTHOOK_YML),
            exec: false,
        });
        out.push(Item::Block {
            path: file.to_owned(),
            begin: "# ferrule:begin",
            end: "# ferrule:end",
            body: "extends:\n  - .ferrule/lefthook.yml\n".to_owned(),
        });
    }
    out
}

/// A top-level `extends:` outside ferrule's block: lefthook takes one
/// list, so the user adds `.ferrule/lefthook.yml` to it.
fn foreign_extends(root: &Path, file: &str) -> bool {
    let text = std::fs::read_to_string(root.join(file)).unwrap_or_default();
    let outside = match block(&text, "# ferrule:begin", "# ferrule:end") {
        Some((s, e)) => format!("{}{}", &text[..s], &text[e..]),
        None => text,
    };
    outside.lines().any(|l| l.starts_with("extends:"))
}

fn write(root: &Path, path: &str, text: &str, exec: bool) -> std::io::Result<()> {
    let full = root.join(path);
    if let Some(dir) = full.parent() {
        std::fs::create_dir_all(dir)?;
    }
    std::fs::write(&full, text)?;
    if exec {
        set_exec(&full)?;
    }
    Ok(())
}

#[cfg(unix)]
fn set_exec(path: &Path) -> std::io::Result<()> {
    use std::os::unix::fs::PermissionsExt;
    let mut p = std::fs::metadata(path)?.permissions();
    p.set_mode(p.mode() | 0o755);
    std::fs::set_permissions(path, p)
}

#[cfg(not(unix))]
fn set_exec(_: &Path) -> std::io::Result<()> {
    Ok(())
}

/// `+a/-b`: lines only the new text has, lines only the old one has.
fn diff_summary(old: &str, new: &str) -> String {
    let mut counts: BTreeMap<&str, i64> = BTreeMap::new();
    for l in new.lines() {
        *counts.entry(l).or_default() += 1;
    }
    for l in old.lines() {
        *counts.entry(l).or_default() -= 1;
    }
    let added: i64 = counts.values().filter(|&&c| c > 0).sum();
    let removed: i64 = -counts.values().filter(|&&c| c < 0).sum::<i64>();
    format!("+{added}/-{removed}")
}

/// `origin/HEAD`'s branch, else git's `init.defaultBranch`, else `main`.
fn main_branch(root: &Path) -> String {
    git::out(
        root,
        &["symbolic-ref", "--short", "-q", "refs/remotes/origin/HEAD"],
    )
    .and_then(|r| r.strip_prefix("origin/").map(str::to_owned))
    .or_else(|| git::out(root, &["config", "--get", "init.defaultBranch"]))
    .filter(|b| !b.is_empty())
    .unwrap_or_else(|| "main".to_owned())
}

/// `text` with its top-level `version` set to `line`, every other line and
/// line ending as it was: a `version` key inside a table is not the pin.
fn pin_version(text: &str, line: &str) -> String {
    let nl = if text.contains("\r\n") { "\r\n" } else { "\n" };
    let mut out = String::with_capacity(text.len() + line.len());
    let mut top = true;
    let mut done = false;
    for l in text.split_inclusive('\n') {
        let bare = l.trim_end_matches(['\n', '\r']);
        let key = bare.trim_start();
        if key.starts_with('[') {
            top = false;
        }
        let is_pin = top
            && !done
            && key
                .strip_prefix("version")
                .is_some_and(|r| r.trim_start().starts_with('='));
        if is_pin {
            out.push_str(line);
            out.push_str(&l[bare.len()..]);
            done = true;
        } else {
            out.push_str(l);
        }
    }
    if done {
        out
    } else {
        format!("{line}{nl}{text}")
    }
}

fn on_path(program: &str) -> bool {
    std::env::var_os("PATH")
        .is_some_and(|p| std::env::split_paths(&p).any(|d| d.join(program).is_file()))
}

/// A new project's `ferrule.toml`.
fn config_text(stack: Stack, main: &str, viewer: bool) -> String {
    let mut out = format!(
        "version = {}\nhosts = [\"claude\"]\nstack = {}\nmain_branch = {}\n\n[backend]\ntracker = \"github\"\nhost = \"github\"\n",
        quote(VERSION),
        quote(stack.as_str()),
        quote(main)
    );
    for (name, cmd) in stack.gauntlet() {
        let _ = write!(
            out,
            "\n[[gauntlet.step]]\nname = \"{name}\"\ncmd = {cmd}\ntimeout = \"30m\"\n"
        );
    }
    if viewer {
        out.push_str("\n[viewer]\ncommand = [\"glow\"]\n");
    }
    out
}

/// `ferrule.toml` created, or its `version` moved to this binary's; the
/// viewer added only where the file has none.
fn ensure_config(root: &Path, opts: &Options, report: &mut Report) -> Result<(), Error> {
    let path = root.join(CONFIG);
    let glow = on_path("glow");
    match std::fs::read_to_string(&path) {
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            let stack = opts.stack.unwrap_or_else(|| Stack::detect(root));
            report.stack = Some(stack);
            report.viewer = glow;
            write(
                root,
                CONFIG,
                &config_text(stack, &main_branch(root), glow),
                false,
            )?;
            report.written.push(CONFIG.to_owned());
        }
        Err(e) => return Err(e.into()),
        Ok(text) => {
            let parsed = config::Config::load(root).ok();
            report.stack = parsed
                .as_ref()
                .and_then(|c| c.stack.as_deref())
                .and_then(Stack::parse);
            let has_viewer = text.lines().any(|l| l.trim() == "[viewer]");
            let mut new = pin_version(&text, &format!("version = {}", quote(VERSION)));
            if !has_viewer && glow {
                let nl = if text.contains("\r\n") { "\r\n" } else { "\n" };
                if !new.ends_with('\n') {
                    new.push_str(nl);
                }
                for part in [nl, "[viewer]", nl, "command = [\"glow\"]", nl] {
                    new.push_str(part);
                }
            }
            report.viewer = has_viewer && parsed.is_some_and(|c| c.viewer.command.is_some())
                || (!has_viewer && glow);
            if new != text {
                std::fs::write(&path, new)?;
                report.written.push(CONFIG.to_owned());
            }
        }
    }
    Ok(())
}

fn ensure_claude_md(root: &Path, lock: &mut Lock, report: &mut Report) -> std::io::Result<()> {
    let path = root.join("CLAUDE.md");
    let text = std::fs::read_to_string(&path).unwrap_or_default();
    if text
        .lines()
        .any(|l| matches!(l.trim(), "@AGENTS.md" | "@./AGENTS.md"))
    {
        return Ok(());
    }
    let sep = if text.is_empty() || text.ends_with("\n\n") {
        ""
    } else if text.ends_with('\n') {
        "\n"
    } else {
        "\n\n"
    };
    std::fs::write(&path, format!("{text}{sep}@AGENTS.md\n"))?;
    lock.claude_md = true;
    report.written.push("CLAUDE.md".to_owned());
    Ok(())
}

/// Where git runs this repository's hooks, and whether that is inside its
/// git directory: a `core.hooksPath` elsewhere (a global one) is shared
/// with other repositories.
fn hooks_dir(root: &Path) -> Option<(PathBuf, bool)> {
    let dir = root.join(git::out(root, &["rev-parse", "--git-path", "hooks"])?);
    let common = root.join(git::out(root, &["rev-parse", "--git-common-dir"])?);
    let own = match (dir.canonicalize(), common.canonicalize()) {
        (Ok(d), Ok(c)) => d.starts_with(c),
        // Not there yet: git creates `hooks` under its own directory.
        (Err(_), Ok(c)) => dir.parent().and_then(|p| p.canonicalize().ok()) == Some(c),
        _ => false,
    };
    Some((dir, own))
}

/// A git hook calling the shim; a checkout without it (another repository
/// sharing the hooks directory) is let through.
fn git_hook_text(name: &str) -> String {
    format!(
        "#!/bin/sh\n# {GENERATED} {VERSION}, edit .ferrule/ instead\nshim=\"$(git rev-parse --show-toplevel)/.ferrule/ferrule\"\n[ -x \"$shim\" ] || exit 0\nexec \"$shim\" hook git {name} \"$@\"\n"
    )
}

/// The git hooks: through lefthook's configuration (an install item), in
/// the hooks directory, or left to the user.
fn ensure_git_hooks(root: &Path, report: &mut Report) -> std::io::Result<()> {
    if let Some(file) = lefthook(root) {
        if foreign_extends(root, file) {
            report.hooks = Some(Hooks::Manual);
            report.hints.push(format!("hint=add .ferrule/lefthook.yml to the extends list of {file}, then run lefthook install"));
        } else {
            report.hooks = Some(Hooks::Lefthook);
            report
                .hints
                .push("hint=run lefthook install so git runs the ferrule hooks".to_owned());
        }
        return Ok(());
    }
    if root.join(".husky").is_dir() {
        report.hooks = Some(Hooks::Manual);
        for name in GIT_HOOKS {
            report.hints.push(format!(
                "hint=add to .husky/{name}: .ferrule/ferrule hook git {name} \"$@\""
            ));
        }
        return Ok(());
    }
    let Some((dir, own)) = hooks_dir(root) else {
        report.hooks = Some(Hooks::Manual);
        report
            .hints
            .push("hint=not a git repository: no git hooks written".to_owned());
        return Ok(());
    };
    if !own {
        report.hooks = Some(Hooks::Manual);
        for name in GIT_HOOKS {
            report.hints.push(format!(
                "hint=core.hooksPath points outside the repository ({}): add to its {name}: .ferrule/ferrule hook git {name} \"$@\"",
                dir.display()
            ));
        }
        return Ok(());
    }
    std::fs::create_dir_all(&dir)?;
    for name in GIT_HOOKS {
        let path = dir.join(name);
        let text = git_hook_text(name);
        // Bytes, not text: a hook of the user's need not be UTF-8, and one
        // that is not must be kept, not taken for absent.
        match std::fs::read(&path) {
            Ok(old) if old == text.as_bytes() => {}
            Ok(old) if !String::from_utf8_lossy(&old).contains(GENERATED) => {
                report.hints.push(format!("hint=kept your .git/hooks/{name}; call .ferrule/ferrule hook git {name} \"$@\" from it"));
            }
            Ok(_) => {
                std::fs::write(&path, &text)?;
                set_exec(&path)?;
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                std::fs::write(&path, &text)?;
                set_exec(&path)?;
            }
            Err(e) => return Err(e),
        }
    }
    report.hooks = Some(Hooks::Git);
    Ok(())
}

/// Sets up or upgrades the project at `root`.
///
/// # Errors
/// [`Error::Foreign`] before anything is written when a generated path
/// holds a file ferrule did not write and `force` is off.
pub fn install(root: &Path, opts: &Options) -> Result<Report, Error> {
    let mut lock = Lock::load(root)?;
    // Everything that could refuse is read before anything is written.
    if root.join(CONFIG).exists() {
        config::Config::load(root).map_err(|e| Error::Config(e.to_string()))?;
    }
    settings::validate(root)?;
    let items = items(root);
    check_markers(root, &items)?;
    if !opts.force {
        for item in &items {
            if let (Item::File { path, text, .. }, Some(cur)) = (item, item.current(root))
                && cur != *text
                && !lock.files.contains_key(path)
            {
                return Err(Error::Foreign(path.clone()));
            }
        }
    }
    let mut report = Report::default();
    ensure_config(root, opts, &mut report)?;
    for item in &items {
        apply(root, item, &mut lock, &mut report)?;
    }
    let config = config::Config::load(root).map_err(|e| Error::Config(e.to_string()))?;
    if settings::apply(root, &deny_rules(&config.guard.allow), &mut lock.deny)? {
        report.written.push(settings::PATH.to_owned());
    }
    ensure_claude_md(root, &mut lock, &mut report)?;
    if !root.join("docs/specs/README.md").exists() {
        write(root, "docs/specs/README.md", SPECS_README, false)?;
        report.written.push("docs/specs/README.md".to_owned());
    }
    ensure_git_hooks(root, &mut report)?;
    if !report.viewer {
        report.hints.push("hint=no viewer: prompt show prints approval files into the agent's context; install glow and rerun ferrule setup install".to_owned());
    }
    VERSION.clone_into(&mut lock.version);
    let text = lock.text();
    if std::fs::read_to_string(root.join(LOCK)).ok().as_deref() != Some(text.as_str()) {
        write(root, LOCK, &text, false)?;
    }
    Ok(report)
}

fn apply(root: &Path, item: &Item, lock: &mut Lock, report: &mut Report) -> std::io::Result<()> {
    let key = item.key();
    let new = item.expected();
    let exec = matches!(item, Item::File { exec: true, .. });
    match item.current(root) {
        Some(cur) if cur == new => {}
        Some(cur) if lock.files.get(&key).is_some_and(|h| *h != hash(&cur)) => {
            let side = format!("{}.ferrule-new", item.path());
            write(root, &side, &item.render(root), exec)?;
            report
                .kept
                .push((item.path().to_owned(), side, diff_summary(&cur, &new)));
            return Ok(());
        }
        _ => {
            write(root, item.path(), &item.render(root), exec)?;
            report.written.push(item.path().to_owned());
        }
    }
    // The file is ferrule's version now: a side copy of an earlier one is
    // stale.
    let side = root.join(format!("{}.ferrule-new", item.path()));
    if side.is_file() {
        std::fs::remove_file(side)?;
    }
    lock.files.insert(key, hash(&new));
    Ok(())
}

/// The `permissions.deny` backstop: every replaced command the project
/// did not re-open, and the files only ferrule writes. A command gets an
/// exact rule and one for it followed by arguments: `git merge:*` alone
/// would also match `git merge-base`.
#[must_use]
pub fn deny_rules(allow: &[String]) -> Vec<String> {
    let mut out: Vec<String> = guard::REPLACED
        .iter()
        .filter(|r| !reopened(r.raw, allow))
        .flat_map(|r| [format!("Bash({})", r.raw), format!("Bash({} :*)", r.raw)])
        .collect();
    for path in [
        "**/.ferrule/state.db",
        "**/.ferrule/ferrule.lock",
        "**/.ferrule/ferrule.toml",
        "**/.claude/settings.json",
        "**/.claude/settings.local.json",
        "**/.claude/agents/fe-*.md",
        "**/.claude/skills/fe-*/SKILL.md",
    ] {
        // An `Edit` rule covers every tool that writes files, `Write` included.
        out.push(format!("Edit({path})"));
    }
    out
}

/// Whether `[guard] allow` re-opens the whole of `raw`, as the guard reads
/// it: an entry's words must be a word prefix of the command. A longer
/// entry (`git push --dry-run`) re-opens one form only, which a deny rule
/// cannot express, so the rule stays.
fn reopened(raw: &str, allow: &[String]) -> bool {
    let words: Vec<&str> = raw.split_whitespace().collect();
    allow.iter().any(|a| {
        let a: Vec<&str> = a.split_whitespace().collect();
        !a.is_empty() && words.starts_with(&a)
    })
}

/// Where the project drifted from what this binary would write: one
/// `path=… reason=…` each, empty when in step.
///
/// # Errors
/// An unreadable lock or settings file.
pub fn check(root: &Path) -> Result<Vec<String>, Error> {
    let lock = Lock::load(root)?;
    check_markers(root, &items(root))?;
    let mut drift = Vec::new();
    let pinned = config::Config::load(root).ok().and_then(|c| c.version);
    if pinned.as_deref() != Some(VERSION) {
        drift.push(format!(
            "path={CONFIG} reason=version pinned={} binary={VERSION}",
            pinned.as_deref().unwrap_or("none")
        ));
    }
    if lock.version != VERSION {
        drift.push(format!(
            "path={LOCK} reason=version locked={} binary={VERSION}",
            if lock.version.is_empty() {
                "none"
            } else {
                &lock.version
            }
        ));
    }
    for item in items(root) {
        let new = item.expected();
        let reason = match item.current(root) {
            None => Some("missing"),
            Some(cur) if cur == new => None,
            Some(cur) => Some(
                if lock
                    .files
                    .get(&item.key())
                    .is_some_and(|h| *h == hash(&cur))
                {
                    "stale"
                } else {
                    "edited"
                },
            ),
        };
        if let Some(r) = reason {
            drift.push(format!("path={} reason={r}", item.path()));
        }
    }
    let config = match config::Config::load(root) {
        Ok(c) => c,
        Err(_) if !root.join(CONFIG).exists() => config::Config::default(),
        Err(e) => return Err(Error::Config(e.to_string())),
    };
    if !settings::in_step(root, &deny_rules(&config.guard.allow), &lock.deny)? {
        drift.push(format!("path={} reason=edited", settings::PATH));
    }
    Ok(drift)
}

#[derive(Debug, Default)]
pub struct Removed {
    pub removed: Vec<String>,
    pub kept: Vec<String>,
}

/// Takes out what install put in: unedited generated files, the marked
/// blocks, the settings entries, the git hooks it wrote, the `CLAUDE.md`
/// line it added. `purge` also removes `.ferrule/` with the board.
///
/// # Errors
/// An unreadable lock or settings file, or a failed write.
pub fn uninstall(root: &Path, purge: bool) -> Result<Removed, Error> {
    let lock = Lock::load(root)?;
    let mut out = Removed::default();
    for key in lock.files.keys() {
        let path = key.strip_suffix("#ferrule").unwrap_or(key);
        let side = root.join(format!("{path}.ferrule-new"));
        if side.is_file() {
            std::fs::remove_file(&side)?;
            out.removed.push(format!("{path}.ferrule-new"));
        }
    }
    for (key, h) in &lock.files {
        if let Some(path) = key.strip_suffix("#ferrule") {
            let full = root.join(path);
            let Ok(text) = std::fs::read_to_string(&full) else {
                continue;
            };
            let (begin, end) = if path == "AGENTS.md" {
                ("<!-- ferrule:begin -->", "<!-- ferrule:end -->")
            } else {
                ("# ferrule:begin", "# ferrule:end")
            };
            if let Some((s, e)) = block(&text, begin, end) {
                let rest = format!("{}{}", &text[..s], &text[e..]);
                if rest.trim().is_empty() {
                    std::fs::remove_file(&full)?;
                } else {
                    std::fs::write(&full, rest)?;
                }
                out.removed.push(path.to_owned());
            }
            continue;
        }
        let full = root.join(key);
        match std::fs::read_to_string(&full) {
            Ok(text) if hash(&text) == *h => {
                std::fs::remove_file(&full)?;
                if let Some(dir) = full.parent()
                    && dir
                        .file_name()
                        .is_some_and(|n| n.to_string_lossy().starts_with("fe-"))
                {
                    let _ = std::fs::remove_dir(dir);
                }
                out.removed.push(key.clone());
            }
            Ok(_) => out.kept.push(key.clone()),
            Err(_) => {}
        }
    }
    if settings::remove(root, &lock.deny)? {
        out.removed.push(settings::PATH.to_owned());
    }
    if lock.claude_md {
        let path = root.join("CLAUDE.md");
        if let Ok(text) = std::fs::read_to_string(&path) {
            let rest: Vec<&str> = text.lines().filter(|l| l.trim() != "@AGENTS.md").collect();
            let rest = rest.join("\n");
            if rest.trim().is_empty() {
                std::fs::remove_file(&path)?;
            } else {
                std::fs::write(&path, rest.trim_end().to_owned() + "\n")?;
            }
            out.removed.push("CLAUDE.md".to_owned());
        }
    }
    // Only this repository's own hooks directory: a shared one never got
    // ferrule's hooks from this install.
    if let Some((dir, true)) = hooks_dir(root) {
        for name in GIT_HOOKS {
            let path = dir.join(name);
            if std::fs::read_to_string(&path).is_ok_and(|t| t.contains(GENERATED)) {
                std::fs::remove_file(&path)?;
            }
        }
    }
    if purge {
        let dir = root.join(".ferrule");
        if dir.exists() {
            std::fs::remove_dir_all(&dir)?;
            out.removed.push(".ferrule/".to_owned());
        }
    } else {
        let _ = std::fs::remove_file(root.join(LOCK));
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ut_markers_crlf_and_problems() {
        let crlf = "a\r\n# ferrule:begin\r\nx\r\n# ferrule:end\r\nb\r\n";
        let (s, e) = block(crlf, "# ferrule:begin", "# ferrule:end").unwrap();
        assert_eq!(&crlf[s..e], "# ferrule:begin\r\nx\r\n# ferrule:end\r\n");
        let p = |t| marker_problem(t, "# ferrule:begin", "# ferrule:end");
        assert_eq!(p(crlf), None);
        assert!(p("# ferrule:begin\nx\n").is_some());
        assert!(p("x\n# ferrule:end\n").is_some());
        assert!(p("# ferrule:end\n# ferrule:begin\n").is_some());
        assert!(p("# ferrule:begin\n# ferrule:end\n# ferrule:begin\n# ferrule:end\n").is_some());
    }

    #[test]
    fn ut_pin_version_touches_the_top_level_key_only() {
        let v = "version = \"9\"";
        assert_eq!(
            pin_version(
                "version = \"1\"\r\nstack = \"rust\"\r\n[x]\r\nversion = 3\r\n",
                v
            ),
            "version = \"9\"\r\nstack = \"rust\"\r\n[x]\r\nversion = 3\r\n"
        );
        assert_eq!(
            pin_version("stack = \"rust\"\n[x]\nversion = 3\n", v),
            "version = \"9\"\nstack = \"rust\"\n[x]\nversion = 3\n"
        );
    }

    #[test]
    fn ut_block_spans_its_markers() {
        let t = "a\n# ferrule:begin\nx\n# ferrule:end\nb\n";
        let (s, e) = block(t, "# ferrule:begin", "# ferrule:end").unwrap();
        assert_eq!(&t[s..e], "# ferrule:begin\nx\n# ferrule:end\n");
        assert_eq!(
            block("x # ferrule:begin\n", "# ferrule:begin", "# ferrule:end"),
            None
        );
    }

    #[test]
    fn ut_diff_summary_counts_lines() {
        assert_eq!(diff_summary("a\nb\nc\n", "a\nc\nd\ne\n"), "+2/-1");
    }

    #[test]
    fn ut_hash_is_fnv1a() {
        assert_eq!(hash(""), "cbf29ce484222325");
        assert_eq!(hash("a"), "af63dc4c8601ec8c");
    }

    #[test]
    fn ut_deny_rules_skip_reopened_commands() {
        let all = deny_rules(&[]);
        assert!(all.contains(&"Bash(git commit)".to_owned()));
        assert!(all.contains(&"Bash(git commit :*)".to_owned()));
        assert!(!all.iter().any(|r| r.starts_with("Bash(git merge:")));
        assert!(all.contains(&"Edit(**/.ferrule/state.db)".to_owned()));
        assert!(!all.iter().any(|r| r.starts_with("Write(")));
        let some = deny_rules(&["gh issue".to_owned()]);
        assert!(!some.iter().any(|r| r.starts_with("Bash(gh issue")));
        assert!(some.contains(&"Bash(gh pr create :*)".to_owned()));
    }

    #[test]
    fn ut_deny_rules_match_allow_by_words() {
        let has = |rules: &[String], raw: &str| rules.contains(&format!("Bash({raw} :*)"));
        let partial = deny_rules(&["gh iss".to_owned()]);
        assert!(has(&partial, "gh issue view"));
        let whole = deny_rules(&["gh issue".to_owned()]);
        assert!(!has(&whole, "gh issue view"));
        let longer = deny_rules(&["git push --dry-run".to_owned()]);
        assert!(has(&longer, "git push"));
    }

    #[test]
    fn ut_config_text_parses() {
        let c: config::Config = toml::from_str(&config_text(Stack::Rust, "trunk", true)).unwrap();
        assert_eq!(c.version.as_deref(), Some(VERSION));
        assert_eq!(c.main_branch, "trunk");
        assert_eq!(c.gauntlet.step.len(), 3);
        assert_eq!(c.viewer.command, Some(vec!["glow".to_owned()]));
    }
}
